In Python, a metaclass is a class that defines how other classes are created. It is like a blueprint for creating classes. 

Here is an example of a simple metaclass in Python:

```python
class MyMeta(type):
    def __new__(cls, name, bases, dct):
        dct['new_attribute'] = 10
        return super(MyMeta, cls).__new__(cls, name, bases, dct)

class MyClass(metaclass=MyMeta):
    pass

print(MyClass.new_attribute)  # Output: 10
```

In this example, `MyMeta` is a custom metaclass that adds a new attribute `new_attribute` with a value of 10 to any class that uses it. The `MyClass` class defines no attributes, but it inherits the `new_attribute` from the metaclass.

Metaclasses are powerful but should be used with caution as they can make code more complex and harder to understand.

To codegen a fib function using llvm-c, we need to follow these steps:

1. Define the LLVM module and function
2. Create the function prototype
3. Define the function body
4. Create the builder for generating IR instructions
5. Generate the IR instructions for the fib function
6. Verify the generated IR code

Here is an example of the outlined process in C code using llvm-c:

```c
#include <stdio.h>
#include <llvm-c/Core.h>

int main() {
    LLVMModuleRef mod = LLVMModuleCreateWithName("fib_module");
    LLVMBuilderRef builder = LLVMCreateBuilder();

    // Create the fib function prototype
    LLVMTypeRef fibArgs[] = { LLVMInt32Type() };
    LLVMTypeRef fibRetType = LLVMInt32Type();
    LLVMTypeRef fibFuncType = LLVMFunctionType(fibRetType, fibArgs, 1, 0);
    LLVMValueRef fibFunc = LLVMAddFunction(mod, "fib", fibFuncType);

    // Define the function body
    LLVMBasicBlockRef entry = LLVMAppendBasicBlock(fibFunc, "entry");
    LLVMPositionBuilderAtEnd(builder, entry);

    LLVMValueRef n = LLVMGetParam(fibFunc, 0);
    LLVMValueRef result = LLVMBuildAlloca(builder, LLVMInt32Type(), "result");

    LLVMBasicBlockRef fibExit = LLVMAppendBasicBlock(fibFunc, "exit");
    LLVMBasicBlockRef fibCond = LLVMAppendBasicBlock(fibFunc, "cond");
    LLVMBasicBlockRef fibBody = LLVMAppendBasicBlock(fibFunc, "body");

    LLVMBuildBr(builder, fibCond);

    LLVMPositionBuilderAtEnd(builder, fibCond);
    LLVMValueRef cmp = LLVMBuildICmp(builder, LLVMIntNE, n, LLVMConstInt(LLVMInt32Type(), 0, 0), "cmp");
    LLVMBuildCondBr(builder, cmp, fibBody, fibExit);

    LLVMPositionBuilderAtEnd(builder, fibBody);
    LLVMValueRef nMinus1 = LLVMBuildSub(builder, n, LLVMConstInt(LLVMInt32Type(), 1, 0), "n-1");
    LLVMValueRef fibNMinus1 = LLVMBuildCall(builder, fibFunc, &nMinus1, 1, "fib_n-1");
    LLVMValueRef nMinus2 = LLVMBuildSub(builder, n, LLVMConstInt(LLVMInt32Type(), 2, 0), "n-2");
    LLVMValueRef fibNMinus2 = LLVMBuildCall(builder, fibFunc, &nMinus2, 1, "fib_n-2");
    LLVMValueRef sum = LLVMBuildAdd(builder, fibNMinus1, fibNMinus2, "sum");
    LLVMBuildStore(builder, sum, result);
    LLVMBuildBr(builder, fibExit);

    LLVMPositionBuilderAtEnd(builder, fibExit);
    LLVMBuildRet(builder, LLVMBuildLoad(builder, result, "final_result"));

    char *error = NULL;
    LLVMVerifyModule(mod, LLVMAbortProcessAction, &error);
    LLVMDisposeMessage(error);

    LLVMDisposeBuilder(builder);

    return 0;
}
```

This code outlines the process of codegen for a fib function in LLVM using llvm-c. Make sure to adhere to correct coding practices like error handling, memory management, and code structuring to ensure a clean and readable codebase.

