```java
import java.util.List;
import java.util.stream.Collectors;

public class ListChecker {

    public static <T> T checkListSize(List<T> list) {
        return list.stream()
                .limit(2)
                .collect(Collectors.collectingAndThen(Collectors.toList(), result -> {
                    if (result.size() > 1) {
                        throw new IllegalArgumentException("List contains more than one entry");
                    } else if (result.size() == 1) {
                        return result.get(0);
                    } else {
                        return null;
                    }
                }));
    }

    public static void main(String[] args) {
        List<String> list1 = List.of("apple");
        List<String> list2 = List.of("banana", "orange");
        List<String> list3 = List.of();

        System.out.println(checkListSize(list1)); // Output: apple
        System.out.println(checkListSize(list2)); // Throws IllegalArgumentException
        System.out.println(checkListSize(list3)); // Output: null
    }
}
```

