    {
        if (showConsole)
        {
            float windowWidth = 600;
            float windowHeight = 400;

            float leftPos = (Screen.width - windowWidth) / 2;
            float topPos = (Screen.height - windowHeight) / 2;

            GUI.Box(new Rect(leftPos, topPos, windowWidth, windowHeight), "");
            GUI.backgroundColor = Color.black;

            float textFieldHeight = 20f;
            float textFieldTopPos = topPos + windowHeight - textFieldHeight - 10f;

            consoleText = GUI.TextField(new Rect(leftPos + 10f, textFieldTopPos, windowWidth - 20f, textFieldHeight), consoleText);

            GUI.Label(new Rect(leftPos + 10f, topPos + 5f, windowWidth - 20f, windowHeight - 30f), commandOutput, guiStyle);

            if (Event.current.isKey && Event.current.keyCode == KeyCode.Return)
