package main

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

func isPrime(num int) bool {
	if num < 2 {
		return false
	}
	for i := 2; i*i <= num; i++ {
		if num%i == 0 {
			return false
		}
	}
	return true
}

func calculatePrimes(n int) []int {
	var primes []int
	num := 2
	for len(primes) < n {
		if isPrime(num) {
			primes = append(primes, num)
		}
		num++
	}
	return primes
}

func main() {
	if len(os.Args) != 2 {
		fmt.Println("Usage: go run main.go <n>")
		return
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		fmt.Println("Invalid input. Please provide a valid number.")
		return
	}

	start := time.Now()
	primes := calculatePrimes(n)
	elapsed := time.Since(start)

	fmt.Printf("First %d prime numbers: %v\n", n, primes)
	fmt.Printf("Calculation took %s\n", elapsed)
}

