#include <stdio.h>
#include <stdlib.h>
#include <time.h>

double monte_carlo_pi(int num_points) {
    int inside_circle = 0;
    double x, y;

    for (int i = 0; i < num_points; i++) {
        x = (double)rand() / RAND_MAX;
        y = (double)rand() / RAND_MAX;

        if (x*x + y*y <= 1) {
            inside_circle++;
        }
    }

    return 4 * (double)inside_circle / num_points;
}

int main() {
    srand(time(0));
    int num_points = 1000000;

    double pi = monte_carlo_pi(num_points);
    printf("Estimated value of Pi using Monte Carlo method: %f\n", pi);

    return 0;
}

