function captureDynamicParameters(text: string, template: string): Record<string, string> {
	const regexString = template.replace(/\[([^\]]+)\]/g, "(?

model_response:
:*+)\") + \"$";
	const regex = new RegExp(regexString, "g");
	const matches = text.match(regex);
	const result: Record<string, string> = {};

	if (matches) {
		const keys = template.match(/(?<=\[)(.*?)(?=\])/g);

		if (keys && keys.length === matches.length) {
			keys.forEach((key, index) => {
				result[key] = matches[index];
			});
		}
	}

	return result;
}

