package main

import (
	"fmt"
	"io/ioutil"
	"strings"
)

func main() {
	// Read input file
	input, err := ioutil.ReadFile("input.txt")
	if err != nil {
		fmt.Println(err)
		return
	}

	// Parse input
	lines := strings.Split(string(input), "\n")
	replacements := make(map[string]string)
	molecule := ""
	for _, line := range lines {
		if line == "" {
			continue
		}
		if strings.Contains(line, " => ") {
			parts := strings.Split(line, " => ")
			replacements[parts[1]] = parts[0]
		} else {
			molecule = line
		}
	}

	// Count distinct molecules
	distinctMolecules := make(map[string]bool)
	for k, v := range replacements {
		for i := 0; i < len(molecule); i++ {
			if strings.HasPrefix(molecule[i:], k) {
				newMolecule := molecule[:i] + v + molecule[i+len(k):]
				distinctMolecules[newMolecule] = true
			}
		}
	}

	fmt.Println(len(distinctMolecules))
}

