Here is an example of JavaScript code to display Pascal's triangle in an HTML canvas:

First, create an HTML file with a canvas element:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pascal's Triangle</title>
  <style>
    canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <canvas id="pascalsTriangle"></canvas>
  <script src="pascalsTriangle.js"></script>
</body>
</html>
```

Next, create a JavaScript file (e.g. pascalsTriangle.js) and add the following code to generate and draw Pascal's triangle in the canvas:

```javascript
const canvas = document.getElementById('pascalsTriangle');
const ctx = canvas.getContext('2d');

const numRows = 10;
const triangle = generatePascalsTriangle(numRows);

function generatePascalsTriangle(numRows) {
  const triangle = [];
  for (let i = 0; i < numRows; i++) {
    triangle[i] = new Array(i + 1);
    triangle[i][0] = triangle[i][i] = 1;
    for (let j = 1; j < i; j++) {
      triangle[i][j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
    }
  }
  return triangle;
}

function drawTriangle() {
  let x = canvas.width / 2;
  let y = 20;
  const padding = 20;

  for (let i = 0; i < triangle.length; i++) {
    let row = triangle[i];
    for (let j = 0; j < row.length; j++) {
      ctx.fillText(row[j], x, y);
      x += padding;
    }
    x = canvas.width / 2 - (i + 1) * padding / 2;
    y += padding;
  }
}

ctx.font = '16px Arial';
ctx.textAlign = 'center';
drawTriangle();
```

This code will generate Pascal's triangle with 10 rows and display it in the canvas element. You can adjust the number of rows by changing the numRows variable. Feel free to customize the styling and positioning of the triangle as needed.

