Here is a sample C++ code that uses the Windows API to list running processes on Windows:

```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <iostream>

int main() {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe;
    pe.dwSize = sizeof(PROCESSENTRY32);

    if (Process32First(snap, &pe)) {
        do {
            std::cout << "Process ID: " << pe.th32ProcessID << " Process Name: " << pe.szExeFile << std::endl;
        } while (Process32Next(snap, &pe));
    }

    CloseHandle(snap);
    return 0;
}
```

This code uses the `CreateToolhelp32Snapshot` function to take a snapshot of the system processes, and then iterates through the processes using the `Process32First` and `Process32Next` functions to retrieve information about each process. It prints out the process ID and process name for each running process.

