std::vector<Leg> Itinerary::travelPlan(std::string startingCityName,
    std::string destinationCityName)
{
    Vertex start = verticesByName[startingCityName];
    Vertex end = verticesByName[destinationCityName];

    // Assume weightMap is a map of Edge to double that represents the distances between vertices
    std::map<Edge, double> weightMap;
    for (auto edge_it = boost::edges(g).first; edge_it != boost::edges(g).second; ++edge_it) {
        Edge edge = *edge_it;
        weightMap[edge] = g[edge].length;
    }

    std::vector<Vertex> path = findWeightedShortestPath(g, start, end, weightMap);

    std::vector<Leg> results;
    if (!path.empty()) {
        for (int i = 0; i < path.size() - 1; ++i) {
            Leg leg;
            leg.fromCity = g[path[i]].city;
            leg.toCity = g[path[i + 1]].city;
            leg.distance = weightMap[boost::edge(path[i], path[i + 1], g).first];
            results.push_back(leg);
        }
    }

    return results;
}

double Itinerary::getLastTripLength() const
{
    return tripLength;
}
