type Person struct {
	Name     string `realDeets:"name"`
	Age      int    `realDeets:"age"`
	Location string `realDeets:"loc"`
}

func main() {
	p := Person{Name: "Alice", Age: 30, Location: "New York"}

	marshaled, err := marshalWithRealDeets(p)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Println(string(marshaled))
}

func marshalWithRealDeets(data interface{}) ([]byte, error) {
	val := reflect.ValueOf(data)
	typ := reflect.TypeOf(data)

	if val.Kind() != reflect.Struct {
		return nil, fmt.Errorf("data must be a struct")
	}

	result := make(map[string]interface{})

	for i := 0; i < val.NumField(); i++ {
		field := typ.Field(i)
		tag := field.Tag.Get("realDeets")

		if tag != "" {
			result[tag] = val.Field(i).Interface()
		}
	}

	return json.Marshal(result)
}
```
In this snippet, the `marshalWithRealDeets` function marshals a struct to JSON by using reflection to process fields with a tag called `realDeets`. This approach allows you to process structs with different field names and structures as long as they have the specified tag.

