Here is an example of a Unity C# script that draws a circle in both black and white as a gizmo:

```csharp
using UnityEngine;

public class CircleGizmo : MonoBehaviour
{
    public float radius = 1f;

    private void OnDrawGizmos()
    {
        // Draw white circle
        Gizmos.color = Color.white;
        DrawCircle(transform.position, radius);

        // Draw black circle
        Gizmos.color = Color.black;
        DrawCircle(transform.position + new Vector3(radius * 2, 0, 0), radius);
    }

    private void DrawCircle(Vector3 center, float radius)
    {
        float step = 0.1f; // Increase the value for smoother circle
        for (float theta = 0; theta < 2 * Mathf.PI; theta += step)
        {
            float x = center.x + radius * Mathf.Cos(theta);
            float y = center.y + radius * Mathf.Sin(theta);
            Vector3 currentPoint = new Vector3(x, y, center.z);
            Gizmos.DrawSphere(currentPoint, 0.05f);
        }
    }
}
```

Simply attach this script to any GameObject in your Unity scene, and you should be able to see both a white and a black circle gizmo drawn in the Scene view. You can adjust the radius of the circle by changing the `radius` variable in the script.

