Here is a Python program that prompts the user daily for their work log and saves the data in a dictionary. The program also allows the user to generate a report for a month based on the collected data in the RTF format:

```python
import datetime
from docx import Document

work_log = {}

def log_work():
    date = datetime.datetime.now().strftime("%Y-%m-%d")
    work_done = input(f"Enter what you worked on for {date}: ")
    work_log[date] = work_done

def generate_report():
    month = input("Enter the month (e.g. January): ")

    doc = Document()
    doc.add_heading(f"Work Report for {month}", level=1)

    for date, work_done in work_log.items():
        if datetime.datetime.strptime(date, "%Y-%m-%d").strftime("%B") == month:
            doc.add_paragraph(f"{date}: {work_done}")

    doc.save(f"Work_Report_{month}.docx")
    print(f"Work report for {month} has been generated.")

def main():
    while True:
        choice = input("Enter 1 to log work for today, 2 to generate a report for a month, or 3 to quit: ")

        if choice == '1':
            log_work()
        elif choice == '2':
            generate_report()
        elif choice == '3':
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

Please note that the above code uses the `python-docx` library for creating Word documents. Install the library by running `pip install python-docx` before executing the code.

