The following VHDL program implements a simple vending machine targeted at the DE-10 standard FPGA board. The vending machine has three input buttons: button_press, coin_insert, and product_selected. It also has three output signals: product_dispensed, coin_return, and display.

```vhdl
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity vending_machine is
port (
    clk : in std_logic;                     -- Clock input
    reset : in std_logic;                    -- Reset signal input
    button_press : in std_logic;             -- Button press input
    coin_insert : in std_logic;              -- Coin insert input
    product_selected : in std_logic;         -- Product selection input
    product_dispensed : out std_logic;       -- Product dispense output
    coin_return : out std_logic;             -- Coin return output
    display : out std_logic_vector(3 downto 0)   -- Display output for product selection
);
end entity vending_machine;

architecture Behavioral of vending_machine is

    type state_type is (idle, product_select, coin_insertion, dispense_product, return_coin);
    signal state, next_state : state_type;

    signal coin_amount : unsigned(3 downto 0) := "0000";
    signal selected_product : std_logic_vector(1 downto 0) := "00";
    signal product_price : unsigned(1 downto 0) := "00";

begin

    process(clk, reset)
    begin
        if reset = '1' then
            state <= idle;
            coin_amount <= "0000";
            selected_product <= "00";
            product_price <= "00";
            product_dispensed <= '0';
            coin_return <= '0'; 
            display <= "0000";
        elsif rising_edge(clk) then
            state <= next_state;
        end if;
    end process;

    process(state, button_press, coin_insert, product_selected)
    begin
        next_state <= state;
        case state is
            when idle =>
                if product_selected = '1' then
                    next_state <= product_select;
                end if;
            when product_select =>
                if button_press = '1' then
                    selected_product <= selected_product + 1;
                    if selected_product = "11" then
                        selected_product <= "00";
                    end if;
                end if;
                if selected_product = "00" then
                    display <= "0000";
                elsif selected_product = "01" then
                    display <= "0001";
                elsif selected_product = "10" then
                    display <= "0010";
                end if;
                if coin_insert = '1' then
                    next_state <= coin_insertion;
                end if;
            when coin_insertion =>
                coin_amount <= coin_amount + 1;
                if coin_amount = "1101" then
                    next_state <= return_coin;
                end if;
                if coin_amount >= product_price then
                    next_state <= dispense_product;
                end if;
            when return_coin =>
                coin_return <= '1';
                product_price <= "00";
                next_state <= idle;
            when dispense_product =>
                product_dispensed <= '1';
                coin_return <= '0';
                if selected_product = "01" then
                    product_price <= "10";
                elsif selected_product = "10" then
                    product_price <= "01";
                end if;
                next_state <= idle;
        end case;
    end process;

end architecture Behavioral;
```

This VHDL program defines a simple state machine that controls the operation of the vending machine. The machine goes through different states based on user input and dispenses the selected product if enough coins have been inserted. The product selection is displayed on a 4-bit display, and the amount of coins inserted is tracked to calculate the selected product's price. The program should be synthesized and implemented on the DE-10 standard FPGA board for the vending machine functionality to be realized.

