            print(f"{target.name} healed for {self.action_config.get('heal_amount')} HP")

        # Add more action types here as needed

    def calculate_damage(self, actor, target):
        damage = self.action_config.get("damage")

        if self.action_config.get("damage_type") == "percentage_target_health":
            damage = target.hp * damage

        elif self.action_config.get("damage_type") == "percentage_actor_health":
