Here is a C# method that transforms the collection of .NET objects into a structure of nested dictionaries as described:

```csharp
using System;
using System.Collections.Generic;

public class MyObject
{
    public string A { get; set; }
    public string B { get; set; }
    public string C { get; set; }
    public string D { get; set; }
    public IReadOnlyDictionary<string, string> TextByLanguage { get; set; }
}

public static Dictionary<string, Dictionary<string, Dictionary<string, Dictionary<string, string>>>> TransformObjects(List<MyObject> objects)
{
    var result = new Dictionary<string, Dictionary<string, Dictionary<string, Dictionary<string, string>>>>();

    foreach (var obj in objects)
    {
        foreach (var language in obj.TextByLanguage)
        {
            if (!result.ContainsKey(language.Key))
            {
                result[language.Key] = new Dictionary<string, Dictionary<string, Dictionary<string, string>>>();
            }

            if (!result[language.Key].ContainsKey(obj.A))
            {
                result[language.Key][obj.A] = new Dictionary<string, Dictionary<string, string>>();
            }

            if (!result[language.Key][obj.A].ContainsKey(obj.B))
            {
                result[language.Key][obj.A][obj.B] = new Dictionary<string, string>();
            }

            if (!result[language.Key][obj.A][obj.B].ContainsKey(obj.C))
            {
                result[language.Key][obj.A][obj.B][obj.C] = new Dictionary<string, string>();
            }

            result[language.Key][obj.A][obj.B][obj.C][obj.D] = language.Value;
        }
    }

    return result;
}
```

You can call this method with a List of MyObject instances and it will return the transformed nested dictionaries structure with the Language, A, B, C, D keys and corresponding text values.

