let snake;
let scl = 20;

function setup() {
  createCanvas(600, 600);
  snake = new Snake();
  frameRate(10);
}

function draw() {
  background(220);

  snake.update();
  snake.show();
}

function keyPressed() {
  if (keyCode === UP_ARROW) {
    snake.dir(0, -1);
  } else if (keyCode === DOWN_ARROW) {
    snake.dir(0, 1);
  } else if (keyCode === LEFT_ARROW) {
    snake.dir(-1, 0);
  } else if (keyCode === RIGHT_ARROW) {
    snake.dir(1, 0);
  }
}

class Snake {
  constructor() {
    this.x = 0;
    this.y = 0;
    this.xspeed = 1;
    this.yspeed = 0;
  }

  update() {
    this.x = this.x + this.xspeed * scl;
    this.y = this.y + this.yspeed * scl;
  }

  show() {
    fill(0);
    rect(this.x, this.y, scl, scl);
  }

  dir(x, y) {
    this.xspeed = x;
    this.yspeed = y;
  }
}
