model_response:
// C++ snippet implementing a segment tree

#include <iostream>
#include <vector>

using namespace std;

vector<int> segmentTree;

void buildSegmentTree(vector<int>& arr, int start, int end, int index) {
    if (start == end) {
        segmentTree[index] = arr[start];
        return;
    }

    int mid = start + (end - start) / 2;
    buildSegmentTree(arr, start, mid, 2 * index + 1);
    buildSegmentTree(arr, mid + 1, end, 2 * index + 2);

    segmentTree[index] = segmentTree[2 * index + 1] + segmentTree[2 * index + 2];
}

int query(int start, int end, int queryStart, int queryEnd, int index) {
    if (start > queryEnd || end < queryStart) {
        return 0;
    }

    if (start >= queryStart && end <= queryEnd) {
        return segmentTree[index];
    }

    int mid = start + (end - start) / 2;
    return query(start, mid, queryStart, queryEnd, 2 * index + 1) + query(mid + 1, end, queryStart, queryEnd, 2 * index + 2);
}

int main() {
    vector<int> arr = {1, 3, 5, 7, 9, 11};
    int n = arr.size();

    segmentTree.resize(4 * n, 0);

    buildSegmentTree(arr, 0, n - 1, 0);

    cout << query(0, n - 1, 1, 3, 0) << endl;

    return 0;
}

