Here is a basic implementation of an OS-like system without using FreeRTOS code:

```c
#include <stdio.h>
#include <stdbool.h>

#define MAX_THREADS 10
#define QUEUE_SIZE 10

// Struct to represent a thread
typedef struct {
    bool isActive;
    void (*function)();
} Thread;

// Global variables
Thread threadQueue[MAX_THREADS];
int front = 0, rear = -1, itemCount = 0;
int semaphore = 1;

// Function prototypes
void enqueue(Thread thread);
Thread dequeue();
void runOS();
void runThread();

// Function to add a thread to the queue
void enqueue(Thread thread) {
    if (itemCount < QUEUE_SIZE) {
        if (rear == MAX_THREADS - 1) {
            rear = -1;
        }
        threadQueue[++rear] = thread;
        itemCount++;
    }
}

// Function to remove a thread from the queue
Thread dequeue() {
    Thread thread = threadQueue[front++];
    if (front == MAX_THREADS) {
        front = 0;
    }
    itemCount--;
    return thread;
}

// Function to run the OS
void runOS() {
    while (true) {
        if (semaphore > 0 && itemCount > 0) {
            Thread thread = dequeue();
            thread.isActive = true;
            runThread(thread);
            thread.isActive = false;
            semaphore--;
        }
    }
}

// Function to run a thread
void runThread(Thread thread) {
    thread.function();
}

// Example task functions
void task1() {
    printf("Running Task 1\n");
}

void task2() {
    printf("Running Task 2\n");
}

int main() {
    Thread thread1 = { .isActive = false, .function = task1 };
    Thread thread2 = { .isActive = false, .function = task2 };

    enqueue(thread1);
    enqueue(thread2);

    while (true) {
        runOS();
    }

    return 0;
}
```

This code provides a basic implementation of an OS-like system with a queue to store threads and a semaphore to control the execution of threads. The `enqueue()` and `dequeue()` functions are used to add and remove threads from the queue, and the `runOS()` function manages the execution of threads based on the semaphore. The example `task1()` and `task2()` functions demonstrate how tasks can be defined and added to the queue.

