Here is the code for a JavaScript class that satisfies the given specifications:

```javascript
import { openDB } from 'idb';

class DataStore {
  constructor() {
    this.dbPromise = openDB('app-data', 1, {
      upgrade(db) {
        db.createObjectStore('data');
      },
    });
  }

  async setItem(key, value) {
    try {
      const db = await this.dbPromise;
      const tx = db.transaction('data', 'readwrite');
      const store = tx.objectStore('data');
      store.put(value, key);
      await tx.done;
    } catch (error) {
      localStorage.setItem(key, JSON.stringify(value));
    }
  }

  async getItem(key) {
    try {
      const db = await this.dbPromise;
      const tx = db.transaction('data', 'readonly');
      const store = tx.objectStore('data');
      return store.get(key);
    } catch (error) {
      return JSON.parse(localStorage.getItem(key));
    }
  }

  async removeItem(key) {
    try {
      const db = await this.dbPromise;
      const tx = db.transaction('data', 'readwrite');
      const store = tx.objectStore('data');
      store.delete(key);
      await tx.done;
    } catch (error) {
      localStorage.removeItem(key);
    }
  }

  async clear() {
    try {
      const db = await this.dbPromise;
      const tx = db.transaction('data', 'readwrite');
      const store = tx.objectStore('data');
      store.clear();
      await tx.done;
    } catch (error) {
      localStorage.clear();
    }
  }
}

const dataStore = new DataStore();

export default dataStore;
```

This class uses the `idb` library to interact with `indexedDB` and falls back to `localStorage` if `indexedDB` is not supported. It provides methods for setting, getting, removing, and clearing data, just like the `localStorage` API. The methods use `async/await` syntax for asynchronous operations.

Sure! Here is a C++ function that finds the closest point on a segment to a surface of a sphere:

```cpp
#include <iostream>
#include <cmath>

struct Point {
    float x, y, z;
};

struct Sphere {
    Point center;
    float radius;
};

struct Segment {
    Point start;
    Point end;
};

float dotProduct(Point p1, Point p2) {
    return p1.x*p2.x + p1.y*p2.y + p1.z*p2.z;
}

Point closestPointOnSegmentToPoint(Point A, Point B, Point P) {
    Point AP = {P.x - A.x, P.y - A.y, P.z - A.z};
    Point AB = {B.x - A.x, B.y - A.y, B.z - A.z};
    float t = dotProduct(AP, AB) / dotProduct(AB, AB);
    if(t < 0) {
        return A;
    } else if(t > 1) {
        return B;
    } else {
        return {A.x + t * AB.x, A.y + t * AB.y, A.z + t * AB.z};
    }
}

Point closestPointOnSphereToPoint(Sphere sphere, Point P) {
    Point PC = {P.x - sphere.center.x, P.y - sphere.center.y, P.z - sphere.center.z};
    float distance = sqrt(dotProduct(PC, PC));
    Point closestPoint;
    if(distance <= sphere.radius) {
        closestPoint = P;
    } else {
        float scale = sphere.radius / distance;
        closestPoint = {
            sphere.center.x + scale * PC.x,
            sphere.center.y + scale * PC.y,
            sphere.center.z + scale * PC.z
        };
    }
    return closestPoint;
}

int main() {
    Sphere sphere = {{0, 0, 0}, 5};
    Segment segment = {{1, 0, 0}, {1, 4, 0}};
    Point closestPoint = closestPointOnSphereToPoint(sphere, closestPointOnSegmentToPoint(segment.start, segment.end, sphere.center));

    std::cout << "Closest point on segment to sphere surface: (" << closestPoint.x << ", " << closestPoint.y << ", " << closestPoint.z << ")" << std::endl;

    return 0;
}
```

This function first finds the closest point on the segment to the center of the sphere. It then calculates the closest point on the sphere's surface to that point. The final result is the closest point on the segment to the surface of the sphere.

