        require(_uniswapV3FactoryAddress != address(0), "Invalid factory");
        require(_stableCoinAddress != address(0), "Invalid USDT address");
        require(_poolFee > 0, "Invalid pool fee");

        address poolAddress = IUniswapV3Factory(_uniswapV3FactoryAddress).getPool(address(this), _stableCoinAddress, _poolFee);
        require(poolAddress != address(0), "Uniswap V3 pool does not exist");

        (uint160 sqrtPriceX96, , , , , , ) = IUniswapV3Pool(poolAddress).slot0();
        uint256 currentPrice = (sqrtPriceX96 * sqrtPriceX96 * 1e18) / (2**192);
        uint256 usdtBalance = IERC20(_stableCoinAddress).balanceOf(address(this));
        if (usdtBalance == 0) {return;}

        uint256 floorPrice = (usdtBalance * 1e18) / (totalSupply() - balanceOf(address(this)));
        require(currentPrice < floorPrice, "Buyback not needed");

        uint256 tokensAtCurrentPrice = (usdtBalance * 1e18) / currentPrice;
        uint256 tokensAtFloorPrice = (usdtBalance * 1e18) / floorPrice;

        if (tokensAtCurrentPrice < tokensAtFloorPrice) {
            uint256 buybackAmount = tokensAtFloorPrice - tokensAtCurrentPrice;

            if (buybackAmount > 0) {
                // First, try swapping on Uniswap V3
                bool success = swapOnV3(buybackAmount,_stableCoinAddress,address(this));
                if (!success) {swapOnV2(buybackAmount, _stableCoinAddress, address(this));}
                emit Buyback(msg.sender, buybackAmount);

            }
        }
    }
}
