            var url = link.textContent;
            if (url.endsWith('.xml')) {
                console.log(url);
                fetch(url)
                    .then(function(response) {
                        return response.text();
                    })
                    .then(findSitemaps);
            }
        });
    }

    fetch(window.location.href)
        .then(function(response) {
            return response.text();
        })
        .then(findSitemaps);
})();
```

