Certainly! Here is a sample code in LaTeX using TikZ and pgfplots to create the described 2d plot visualization:

```latex
\documentclass{standalone}
\usepackage{pgfplots}
\usetikzlibrary{patterns}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    grid=both,
    grid style={dashed, gray!30},
    axis lines=middle,
    xlabel=$x$,
    ylabel=$y$,
    xmin=0, ymin=0,
    xmax=10, ymax=10,
    xtick={2,4,6,8},
    ytick={2,4,6,8},
    xticklabels={$x$, $y_1$, $y_2$, $y_3},
    yticklabels={$x$, $y_1$, $y_2$, $y_3},
    tick style={draw=none},
    ticklabel style={font=\tiny},
    enlargelimits=false,
]

% Points
\addplot[only marks, mark=*, mark size=2pt] coordinates {(2,6) (4,4) (6,7) (8,5)};
\addplot[only marks, mark=*, mark size=3pt, fill=red] coordinates {(4,6)};
\node at (4,6) [above right] {$x$};
\node at (2,6) [above left] {$y_1$};
\node at (4,4) [above left] {$y_2$};
\node at (6,7) [below right] {$y_3$};

% Shading
\draw[pattern=north west lines, pattern color=red!30] (4,4) -- (4,6) -- (6,7) -- (8,5) -- cycle;

\end{axis}
\end{tikzpicture}

\end{document}
```

This code will create a 2d plot with a point labeled as $x$ being dominated by three other points labeled $y_1$, $y_2$, and $y_3. The region to the top right of $x$ will be shaded pale red, with axis-parallel dashed lines going through the point $x. Feel free to customize the colors, styles, and labels to suit your specific needs.

One alternative way to create a macOS SwiftUI keyboard tester that accommodates different keyboard layouts is to dynamically generate the keyboard keys based on the user's current keyboard layout.

You can achieve this by querying the system for the current keyboard layout and then generating the keys accordingly. Here's a simplified example to get you started:

1. First, you can create a view model to handle the logic of dynamically generating the keyboard keys based on the current layout:

```swift
import SwiftUI

class KeyboardTesterViewModel: ObservableObject {
    @Published var keyboardKeys: [String] = []

    func generateKeyboardKeys() {
        // Logic to generate keyboard keys based on current layout
        // For simplicity, let's just generate alphabet keys
        keyboardKeys = Array("abcdefghijklmnopqrstuvwxyz").map { String($0) }
    }
}
```

2. Next, create the SwiftUI view that will display the generated keys:

```swift
import SwiftUI

struct KeyboardTesterView: View {
    @StateObject var viewModel = KeyboardTesterViewModel()

    var body: some View {
        VStack {
            ForEach(viewModel.keyboardKeys, id: \.self) { key in
                Text(key)
                    .padding()
            }
        }
        .onAppear {
            viewModel.generateKeyboardKeys()
        }
    }
}
```

3. Finally, you can use the `KeyboardTesterView` in your app to test the keyboard functionality:

```swift
import SwiftUI

@main
struct KeyboardTesterApp: App {
    var body: some Scene {
        WindowGroup {
            KeyboardTesterView()
        }
    }
}
```

This approach allows you to dynamically generate the keyboard keys based on the user's current keyboard layout, providing a more flexible and scalable solution compared to hardcoding all the keys. You can further customize the logic in the `generateKeyboardKeys()` method to accommodate different keyboard layouts and key configurations.

