"fix this i need every thread to read diffirent line#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <semaphore.h>
#include <signal.h>
#include <time.h>

#define NUM_THREADS 4
#define NUM_LINES 100
#define NUMBERS_PER_LINE 50

sem_t *semaphore;
int global_sum = 0;
int global_sum_per_line[NUM_LINES];
int global_sum_per_line2[NUM_LINES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    FILE *fp;
    int start_line;
    int end_line;
} ThreadArgs;

void generate_random_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }
    int allthenumberstogether = 0;
    for (int i = 0; i < NUM_LINES; i++) {
        int tempsum = 0;
        for (int j = 0; j < NUMBERS_PER_LINE; j++) {
            int randomnumber = rand() % 101;
            fprintf(fp, "%d ", randomnumber);
            allthenumberstogether += randomnumber;
            tempsum += randomnumber;
        }
        global_sum_per_line[i] = tempsum;
        fprintf(fp, "\n");
    }
    for (int i = 0; i < NUM_LINES; i++) {
        printf("Line %d sum: %d\n", i + 1, global_sum_per_line[i]);
    }
    printf("Total sum: %d\n", allthenumberstogether);
    fclose(fp);
}

void *reader_thread(void *arg) {
    ThreadArgs *thread_args = (ThreadArgs *)arg;
    FILE *fp = thread_args->fp;
    int local_sum = 0;
    int num, count = 0;

    for (int line = thread_args->start_line; line <= thread_args->end_line; line++) {
        fseek(fp, line * (NUMBERS_PER_LINE + 1), SEEK_SET);
        for (int j = 0; j < NUMBERS_PER_LINE; j++) {
            if (fscanf(fp, "%d", &num) == 1) {
                local_sum += num;
                count++;
            }
        }
        if (count == NUMBERS_PER_LINE) {
            pthread_mutex_lock(&mutex);
            global_sum_per_line2[line - 1] = local_sum;
            global_sum += local_sum;
            pthread_mutex_unlock(&mutex);
            local_sum = 0;
            count = 0;
        }
    }
    for(int i = 0; i < NUM_LINES; i++) {
        printf("2 Line %d sum: %d\n", i + 1, global_sum_per_line2[i]);
    }

    free(thread_args);
    return NULL;
}

void signal_handler(int signum) {
    char response;
    printf("Received signal %d. Do you really want to terminate (y/n)?

model_response:
    scanf("%c", &response);
    if (response == 'y' || response == 'Y') {
        sem_post(semaphore);
    } else {
        printf("Continuing...\n");
    }
}

int main() {
    srand(time(NULL));
    generate_random_data("random_data.txt");

    semaphore = sem_open("/my_semaphore", O_CREAT, 0644, 0);
    if (semaphore == SEM_FAILED) {
        perror("sem_open failed");
        exit(EXIT_FAILURE);
    }

    FILE *fp = fopen("random_data.txt", "r");
    if (!fp) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        ThreadArgs *args = (ThreadArgs *)malloc(sizeof(ThreadArgs));
        args->fp = fp;
        args->start_line = i * NUM_LINES / NUM_THREADS;
        args->end_line = (i + 1) * NUM_LINES / NUM_THREADS - 1;
        pthread_create(&threads[i], NULL, reader_thread, args);
    }

    signal(SIGINT, signal_handler);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_close(semaphore);
    sem_unlink("/my_semaphore");
    fclose(fp);
    pthread_mutex_destroy(&mutex);

    return 0;
}

