model_response:
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@uniswap/v3-periphery/contracts/interfaces/ISwapRouter.sol";
import "@uniswap/v2-periphery/contracts/interfaces/IUniswapV2Router02.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract FeeSeller is ReentrancyGuard {
    address private _stableCoinAddress = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address private _swapRouterAddressV3 = 0x1F98431c8aD98523631AE4a59f267346ea31F984;
    address private _swapRouterAddressV2 = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    uint private _poolFee = 500;

    event FeeSwapped(address tokenIn, address tokenOut, uint256 amount);

    function sellFee() public {
        uint fee = balanceOf(address(this));

        try this.swapOnv3(fee, address(this), _stableCoinAddress) {
            // success
        } catch {
            try this.swapOnV2(fee, address(this), _stableCoinAddress) {} catch {}
        }
    }

    function swapOnv3(uint256 amount, address _tokenIn, address _tokenOut) public nonReentrant returns (bool) {
        IERC20(_tokenIn).safeIncreaseAllowance(_swapRouterAddressV3, amount);

        ISwapRouter(_swapRouterAddressV3).exactInputSingle(
            ISwapRouter.ExactInputSingleParams({
                tokenIn: _tokenIn,
                tokenOut: _tokenOut,
                fee: _poolFee,
                recipient: address(this),
                deadline: block.timestamp + 600,
                amountIn: amount,
                amountOutMinimum: 0,
                sqrtPriceLimitX96: 0
            })
        );

        emit FeeSwapped(_tokenIn, _tokenOut, amount);
        return true;
    }

    function swapOnV2(uint256 amount, address _tokenIn, address _tokenOut) public nonReentrant returns (bool) {
        address[] memory path = new address[](2);
        path[0] = _tokenIn;
        path[1] = _tokenOut;

