Here is a code in C language to efficiently reverse the contents of a list and store it again in the same list:

```c
#include <stdio.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

void reverseList(Node** head) {
    Node* prev = NULL;
    Node* current = *head;
    Node* next = NULL;

    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    *head = prev;
}

void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d ", current->data);
        current = current->next;
    }
    printf("\n");
}

int main() {
    Node* head = NULL;
    Node* second = NULL;
    Node* third = NULL;

    head = (Node*)malloc(sizeof(Node));
    second = (Node*)malloc(sizeof(Node));
    third = (Node*)malloc(sizeof(Node));

    head->data = 1;
    head->next = second;

    second->data = 2;
    second->next = third;

    third->data = 3;
    third->next = NULL;

    printf("Original list: ");
    printList(head);

    reverseList(&head);

    printf("Reversed list: ");
    printList(head);

    return 0;
}
```

This code defines a linked list structure with a function `reverseList` that reverses the order of elements in the list and updates the head pointer. The `printList` function is used to print the elements of the list. In the `main` function, a list with three elements is created, printed, reversed, and printed again.

