      if (this.votes.length === this.players.length) {
        this.endTurn();
      }
    }




    endTurn() {
      const votes = this.votes.reduce((acc, vote) => {
        acc[vote.suspectId] = (acc[vote.suspectId] || 0) + 1;
        return acc;
      }, {});
      const maxVotes = Math.max(...Object.values(votes));
      const mostVoted = Object.keys(votes).filter(id => votes[id] === maxVotes);
      if (mostVoted.includes(this.murderer)) {
        this.broadcast('真凶被推断出来了! 其余玩家获胜!');
      } else if (--this.turns) {
        this.broadcast('真凶还在逍遥法外! 下一回合开始.');
      } else {
        this.broadcast('真凶逍遥法外! 真凶获胜!');
