  ctx.command('murder-mystery.send', '发送消息')
  .channelFields(['murder-mystery.sessionId'])
  .option('message', '-m <message>  要发送的消息')
  .action(({ session, options }) => {
      const game = getSession(session.channel['murder-mystery.sessionId']);
      try {
        game.sendMessage(session.userId, options.message);
        return '你的消息已经发送!';
      } catch (err) {
        return err.message;
      }
    });


  ctx.command('murder-mystery.vote', '投票')
    .channelFields(['murder-mystery.sessionId'])
    .option('suspect', '-s <id>  嫌疑人的 id')
    .action(({ session, options }) => {
      const game = getSession(session.channel['murder-mystery.sessionId']);
      try {
        game.vote(session.userId, options.suspect);
        return '你的投票已经记录!';
      } catch (err) {
        return err.message;
      }
    });

  }
);"

