Here's a JavaScript code that counts to the 1000th prime number:

```javascript
function isPrime(num) {
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return num > 1;
}

function findNthPrime(n) {
  let count = 0;
  let num = 2;
  let prime;

  while (count < n) {
    if (isPrime(num)) {
      prime = num;
      count++;
    }
    num++;
  }

  return prime;
}

const nthPrime = findNthPrime(1000);
console.log("The 1000th prime number is:", nthPrime);
```

This code uses a helper function `isPrime` to check if a number is prime or not. It then uses a loop to iterate through numbers and find the 1000th prime number using the `findNthPrime` function. The result is then printed to the console.

Yes, you can remove a parameter from the query string URL in JavaScript. You can achieve this by manipulating the URL string using various methods such as split, splice, join, and replace.

Here is an example of how you can remove a specific parameter from a query string URL:

```javascript
// Sample query string URL
let queryString = 'https://example.com/page?param1=value1&param2=value2&param3=value3';

// Function to remove a parameter from the query string
function removeQueryParam(url, param) {
  let urlParts = url.split('?');
  if (urlParts.length >= 2) {
    let params = urlParts[1].split('&');
    for (let i = params.length - 1; i >= 0; i--) {
      let keyValue = params[i].split('=');
      if (keyValue[0] === param) {
        params.splice(i, 1);
      }
    }
    return urlParts[0] + (params.length > 0 ? '?' + params.join('&') : '');
  }
  return url;
}

let updatedQueryString = removeQueryParam(queryString, 'param2');
console.log(updatedQueryString); // Output: https://example.com/page?param1=value1&param3=value3
```

In this example, the `removeQueryParam` function accepts the query string URL and the parameter to be removed. It then splits the URL into separate parts based on the `?` delimiter, iterates over the parameters in the query string to find and remove the specified parameter, and reconstructs the URL with the updated parameters.

