Here is a basic example of a JavaScript code block that simulates a two-turn game where 12 people in a cafeteria allocate themselves to 12 seats based on a score of how much they like the people they are sitting directly next to:

```javascript
// Initialize 12 people with random scores of how much they like each other
const people = [];
for (let i = 1; i <= 12; i++) {
  const scores = [];
  for (let j = 0; j < 12; j++) {
    scores.push(Math.floor(Math.random() * 10) + 1);
  }
  people.push({ id: i, scores: scores });
}

// First turn: seat people randomly
const seats = [];
let availableSeats = [...Array(12).keys()];
people.forEach(person => {
  const seatIndex = availableSeats[Math.floor(Math.random() * availableSeats.length)];
  seats[seatIndex] = person.id;
  availableSeats = availableSeats.filter(seat => seat !== seatIndex);
});

// Second turn: seat people next to those they like the most
for (let i = 0; i < 12; i++) {
  const prevPerson = people.find(person => person.id === seats[i - 1]) || { scores: Array(12).fill(0) };
  const nextPerson = people.find(person => person.id === seats[i + 1]) || { scores: Array(12).fill(0)};

  const availablePeople = people.filter(person => !seats.includes(person.id));

  // Sort available people based on how much they like sitting next to the previous and next person
  availablePeople.sort((a, b) => {
    const aScore = prevPerson.scores[a.id - 1] + nextPerson.scores[a.id - 1];
    const bScore = prevPerson.scores[b.id - 1] + nextPerson.scores[b.id - 1];
    return bScore - aScore;
  });

  // Seat the person who likes sitting next to the previous and next person the most
  seats[i] = availablePeople[0].id;
}

console.log("Final seating arrangement:");
seats.forEach((personId, index) => {
  console.log(`Seat ${index + 1}: Person ${personId}`);
});
```

This code randomly seeds the scores of how much each person likes another and then simulates the seating allocation process. It first seats people randomly and then reseats them based on how much they like sitting next to the people around them.

Here is a simple implementation of the Stoer-Wagner algorithm in Swift:

```swift
// Helper functions
func minCut(graph: [[Int]]) -> Int {
    var numVertices = graph.count
    var a: [Bool] = Array(repeating: false, count: numVertices)
    var bestCutSize = Int.max

    for _ in 0..<numVertices-1 {
        var v = -1
        var maxs = -1
        for i in 0..<numVertices {
            if !a[i] {
                let s = graph[i].reduce(0, +)
                if s > maxs {
                    maxs = s
                    v = i
                }
            }
        }

        a[v] = true

        var prev = v
        for _ in 0..<numVertices-1 {
            if !a[v] {
                a[v] = true
                for i in 0..<numVertices {
                    if !a[i] {
                        graph[prev][i] += graph[v][i]
                        graph[i][prev] += graph[v][i]
                    }
                }
                prev = v
            }

            v = -1
            maxs = -1
            for i in 0..<numVertices {
                if !a[i] {
                    let s = graph[i].reduce(0, +)
                    if s > maxs {
                        maxs = s
                        v = i
                    }
                }
            }
        }

        var cutSize = 0
        for i in 0..<numVertices {
            if !a[i] {
                cutSize += graph[i].reduce(0, +)
            }
        }

        bestCutSize = min(bestCutSize, cutSize)
    }

    return bestCutSize
}

// Example usage
let graph = [[0, 2, 0, 3],
             [2, 0, 2, 0],
             [0, 2, 0, 2],
             [3, 0, 2, 0]]

let minCutSize = minCut(graph: graph)
print("Minimum cut size: \(minCutSize)")
```

This implementation takes an adjacency matrix representation of a weighted undirected graph as input and returns the size of the minimum cut. The implementation follows the basic steps of the Stoer-Wagner algorithm as described in the algorithm's pseudocode.

