Here is the C code that opens a file and prints the value of each bit in the file byte by byte:

```c
#include <stdio.h>

int main() {
    FILE *file = fopen("example.txt", "rb");
    if(file == NULL) {
        perror("Error opening file");
        return 1;
    }

    int byte;
    while((byte = fgetc(file)) != EOF) {
        for(int i = 0; i < 8; i++) {
            int bit = (byte >> i) & 1;
            printf("%d", bit);
        }
    }

    fclose(file);
    return 0;
}
```

Now, here is the equivalent code in Rust with more explanation:

```rust
use std::fs::File;
use std::io::{BufReader, Read};

fn main() {
    let file = File::open("example.txt").expect("Error opening file");
    let mut reader = BufReader::new(file);

    let mut byte = [0u8; 1];
    while reader.read(&mut byte).unwrap() > 0 {
        for i in 0..8 {
            let bit = (byte[0] >> i) & 1;
            print!("{}", bit);
        }
    }
}
```

